CREATE TABLE IF NOT EXISTS inspection_followups(inspection_id TEXT NOT NULL REFERENCES inspections(id),answer_key TEXT NOT NULL,work_order_id TEXT NOT NULL REFERENCES work_orders(id),created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,PRIMARY KEY(inspection_id,answer_key));
CREATE TABLE IF NOT EXISTS spending_approvals(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id),work_order_id TEXT NOT NULL REFERENCES work_orders(id),amount_minor INTEGER NOT NULL CHECK(amount_minor>0),currency TEXT NOT NULL DEFAULT 'USD',description TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','declined','cancelled')),created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,decided_by TEXT REFERENCES users(id),decided_at TEXT,decision_note TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS approvals_work ON spending_approvals(work_order_id,status);
CREATE TABLE IF NOT EXISTS inspection_plans(id TEXT PRIMARY KEY,property_id TEXT NOT NULL UNIQUE REFERENCES properties(id),assigned_to TEXT NOT NULL REFERENCES users(id),interval_days INTEGER NOT NULL CHECK(interval_days BETWEEN 1 AND 3650),next_due TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inspection_occurrences(plan_id TEXT NOT NULL REFERENCES inspection_plans(id),due_date TEXT NOT NULL,inspection_id TEXT NOT NULL REFERENCES inspections(id),PRIMARY KEY(plan_id,due_date));
CREATE TABLE IF NOT EXISTS automation_settings(organization_id TEXT PRIMARY KEY REFERENCES organizations(id),enabled INTEGER NOT NULL DEFAULT 0,last_run TEXT,last_error TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS maintenance_assignments(plan_id TEXT PRIMARY KEY REFERENCES maintenance_plans(id),user_id TEXT NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS user_mfa(user_id TEXT PRIMARY KEY REFERENCES users(id),secret TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,last_step INTEGER NOT NULL DEFAULT -1,recovery_hashes TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL);
